/**  How far an install has got, for the window to show. */
export type InstallProgress = {
	/**  What the install is doing. */
	step: InstallStep,
	/**
	 *  The bytes done: of the download checked, of the release downloaded, or of the download
	 *  unpacked.
	 */
	done: number,
	/**  The bytes to do. */
	total: number,
};

/**  Where an install was found, in the order the list shows them. */
export type InstallSource = 
/**  The live game, in the Riot client's list or the usual folders. */
"live" | 
/**  The PBE, in the Riot client's list or the usual folders. */
"pbe" | 
/**  The install of a running client, in a folder of another name. */
"running" | 
/**  A folder a person added. */
"added";

/**  What a download of a release is doing. */
export type InstallStep = 
/**
 *  What a download holds already is read again for its digest: the bytes a stopped download
 *  kept, before the rest is asked for, or a file downloaded whole before.
 */
"check" | 
/**  Its files are downloading. */
"download" | 
/**  What was downloaded is unpacking. */
"unpack";

/**  One install as the list shows it. */
export type InstallView = {
	/**  The install's root, as the settings hold it. */
	path: string,
	/**  Where it was found. */
	source: InstallSource,
	/**  The build it says it is. None when it does not open or does not say. */
	build: string | null,
	/**  Whether it is an install: its data folder is there. */
	readable: boolean,
	/**  Whether it is the install a run reads. */
	chosen: boolean,
};

/**
 *  A file kept where the run would drop it as a stale copy (#ADR-0098): by its WAD's name and
 *  its path in that WAD, or its path hash as sixteen hex digits.
 */
export type KeptFileView = {
	/**  The WAD's name: `lux.wad.client`. */
	wad: string,
	/**  The file's path in the WAD. */
	path: string,
};

/**  An index the app installed that the settings do not choose. */
export type KeptIndex = {
	/**  Its folder. */
	dir: string,
	/**  The newest build it holds. */
	newest_build: string,
	/**  How many builds it holds. */
	builds: number,
	/**  Its bytes on disk. */
	bytes: number,
};

/**  The files and bytes of one kind, as `reforge-magic` names kinds. */
export type KindCount = {
	/**  The kind. */
	kind: string,
	/**  How many files and entries are of it. */
	files: number,
	/**  Their bytes. */
	bytes: number,
};

/**  The builds a key was present in, from the first to the last. */
export type LifeView = {
	/**  The first build. */
	first: BuildView,
	/**  The last build. */
	last: BuildView,
	/**  How many positions the life spans, both ends counted. */
	builds: number,
};

/**  A bin a bin links. */
export type LinkView = {
	/**  Its path, spelled, else its hash. */
	path: string,
	/**  Its path hash, as sixteen hex digits. */
	hash: string,
};

/**  A path looked up in the history. */
export type LookupView = {
	/**  The path, spelled through the tables, else as asked, else its hash. */
	path: string,
	/**  Its path hash, as sixteen hex digits. */
	hash: string,
	/**  The builds some WAD held a file at the path. None when the game never held one. */
	life: LifeView | null,
	/**  The kind of the first file seen there, as the census history spells it. */
	kind: string | null,
	/**  The build the rest is answered at. */
	at: BuildView,
	/**  The files the game's WADs held at the path at that build. */
	placed: PlacedView[],
	/**  The game objects that named the path, oldest first, up to [`MAX_NAMED_BY`]. */
	named_by: NamedByView[],
	/**  Whether more objects named the path than `named_by` holds. */
	named_by_capped: boolean,
	/**  The bin at the path at that build. None when the file there is no bin, or none is. */
	bin: BinLookup | null,
};

/**  How a file stands against the stage before. */
export type Mark = 
/**  The same bytes at the same place. */
"same" | 
/**  Other bytes at the same place. */
"changed" | 
/**  At a place the stage before had none at. */
"added" | 
/**  At a place the stage before had, and this stage has not. */
"removed";

/**  An archive read alone. */
export type ModPeek = {
	/**  The mod, as its archive and `META/info.json` name it. */
	meta: ModView,
	/**  The characters its paths name, each with its slots. */
	characters: CharacterPeek[],
	/**
	 *  Its thumbnail as a `data:` URL: the WebP the library encoded from the mod's image
	 *  (#ADR-0051), never the archive's own bytes.
	 */
	thumbnail: string | null,
};

/**  The mod, as its archive and `META/info.json` name it. */
export type ModView = {
	/**  The archive's file name. */
	file_name: string,
	/**  The first twelve hex digits of the archive's SHA-256. */
	mod_id: string,
	/**  Its name. */
	name?: string | null,
	/**  Its author. */
	author?: string | null,
	/**  Its version. */
	version?: string | null,
	/**  Its description. */
	description?: string | null,
};

/**  A game object that named the path. */
export type NamedByView = {
	/**  The path of the object's bin, spelled, else its hash. */
	bin: string,
	/**  The bin's path hash, as sixteen hex digits. */
	bin_hash: string,
	/**  The object's entry name, spelled, else its hash. */
	entry: string,
	/**  The entry hash, as eight hex digits. */
	entry_hash: string,
	/**  The builds the object named the path. */
	life: LifeView,
};

/**  An object a fixup changed, as the run spells it. */
export type ObjectView = {
	/**  Its id in the report: `%o14`. */
	id: string,
	/**  Its entry name, else its hash as eight hex digits. */
	entry: string,
	/**  Its class's name, else the hash as eight hex digits. */
	class: string,
	/**  The bin it is in: the bin's path, else its hash as sixteen hex digits. */
	bin: string,
};

/**  Where a kept run came from (#ADR-0096). */
export type Origin = 
/**  A run of the app's that wrote its package. */
"run" | 
/**  A project file imported: a run with its load, its raw snapshot and their bytes. */
"project" | 
/**  A package's embedded evidence (#ADR-0041), opened as a run with no snapshots. */
"package";

/**  Where a unit's work comes from. */
export type OriginView = {
	/**  `base`, `premium`, `custom` or `unknown`. */
	verdict: string,
	/**  The premium skin, for a premium origin. */
	slot?: number | null,
};

/**  How one archive's run ended. */
export type Outcome = 
/**  The package was written. */
{ outcome: "written" } | 
/**  A finding the settings block refused the write. */
{ outcome: "refused" } | 
/**  A fatal finding ended the run after `read`. */
{ outcome: "halted"; 
/**  The finding's code. */
code: string } | 
/**  The batch's cancel ended the run. */
{ outcome: "cancelled"; 
/**  The stage it ended. */
stage: StageName } | 
/**  An input did not answer, or the run did not start. */
{ outcome: "fault"; 
/**  Why, as text from outside the app. */
detail: string } | 
/**  The archive does not read: a fatal finding ended `read`. */
{ outcome: "unreadable" };

/**  Which `fixup.*` finding a change counts under: its code is `fixup.` and this. */
export type OutcomeView = 
/**  A value converted to the form the target build reads. */
"changed" | 
/**  A value removed with nothing lost. */
"removed" | 
/**  A value removed that the mod's own build read. */
"lost" | 
/**  A value with no conversion, left as it is. */
"unconvertible";

/**
 *  A store whose rows' file another build made, and what a reset of it loses, read from the
 *  file with queries both shapes answer.
 */
export type Outdated = {
	/**  The format the file says it is of. 0 when it does not say. */
	format: number,
	/**  The runs it holds. 0 when they do not count. */
	runs: number,
	/**  The runs a person marked kept. 0 when they do not count. */
	kept: number,
	/**  The bytes of the rows' file. */
	rows_bytes: number,
	/**  The bytes of the run tier, which a reset empties. */
	tier_bytes: number,
};

/**  The packages the two runs built. */
export type PackageDiff = {
	/**  The first run's. */
	a: PackageView | null,
	/**  The second run's. */
	b: PackageView | null,
};

/**  The package a run built. */
export type PackageView = {
	/**  The project's name. */
	name: string,
	/**  Its version. */
	version: string,
	/**  How many chunks it holds. */
	chunks: number,
	/**  How many patches it holds. */
	patches: number,
	/**
	 *  Its thumbnail as a `data:` URL: the WebP the library encoded from the mod's image,
	 *  never the archive's own bytes (#ADR-0051).
	 */
	thumbnail: string | null,
};

/**  What a stage gave the views, sent to the window as the stage ends. */
export type PartView = 
/**
 *  The names of the report's tables, after `load`: what a finding raised from then on
 *  names by id (`%w0`, `%f12`, `%c0`, `%u0`).
 */
{ part: "names"; 
/**  A name for each id, as `RunView::names` holds them. */
names: { [key in string]: string } } | 
/**  What the fixups changed, after `fix`. */
{ part: "changes"; 
/**  What each fixup did, in the order they ran. */
changes: FixupChanges[]; 
/**  The objects they changed. */
objects: ObjectView[] } | 
/**  The decisions, after `decide`. */
{ part: "targets"; 
/**  The decisions. */
targets: TargetsView } | 
/**  The package, after `build`. */
{ part: "package"; 
/**  The package. */
package: PackageView };

/**  A place the window can show. */
export type Place = 
/**  The package the last run wrote, selected in its folder. */
"written" | 
/**  The package a kept run wrote, selected in its folder. */
({ run: {
	/**  The run's number in the store. */
	id: number,
} }) & { install?: never } | 
/**  A game install of the list, detected or added (#ADR-0101). */
({ install: {
	/**  Its root, as the list gives it. */
	path: string,
} }) & { run?: never } | 
/**  The hash cache. */
"hashes" | 
/**  The folder of the schema database. */
"schema" | 
/**  The history index. */
"index" | 
/**  The app's clone of the census history. */
"census";

/**  A file a WAD of the game held at the path. */
export type PlacedView = {
	/**  The WAD's path in the manifest. */
	wad: string,
	/**  The file's key, the head of its SHA-256, as 32 hex digits. */
	content: string,
	/**  The builds the WAD held the file there without a break. */
	life: LifeView,
};

/**  A policy: how a target is chosen, and how much animation reuse is accepted. */
export type PolicyView = {
	/**  `auto`, `base`, `origin`, `slot` or a skin number. */
	target: string,
	/**  `block`, `same-joints`, `own-rig` or `allow`. */
	anim_reuse: string,
};

/**  One question of the guided view. */
export type Question = {
	/**
	 *  Its id, the same across runs of the mod: its kind and its subject, so that an answer
	 *  is kept when a rerun asks again.
	 */
	id: string,
	/**  What it is about. */
	kind: QuestionKind,
	/**  The finding it is asked from, by its id. */
	finding: number,
	/**  The unit, character or WAD, as the view's names spell it. */
	subject: string,
	/**  The choices. */
	choices: Choice[],
	/**  The default's index among the choices: what the run did. */
	chosen: number,
	/**  The mod's own facts the question names, the finding's message first. */
	facts: string[],
};

/**  What a question is about, which gives its title. */
export type QuestionKind = 
/**  Files that are the game's older bytes (`file.stale`). */
"stale-files" | 
/**  A unit the policy's default placed or left (`target.*`). */
"unit-target" | 
/**  Units of one rank on one slot, each leaving it (`target.conflict`). */
"slot-conflict" | 
/**  Units at slots the port does not change (`unit.left`). */
"other-slots" | 
/**  Clips whose events are cut from the mod's own events bank (`audio.carried`). */
"events-bank" | 
/**  A mod made for several skins on purpose (`rework.restoration`). */
"several-skins" | 
/**  An error that refuses the write. */
"blocking-error";

/**  A record as the list shows it. */
export type RecordHead = {
	/**  Its code as a citation: `#GAME-CHANGE-0005`. */
	code: string,
	/**  The series it is in. */
	series: Series,
	/**  Its number in the series. */
	number: number,
	/**  The heading's text after the code. */
	title: string,
	/**  An ADR's status line as written: `Accepted (2026-10-04)`. None for the other series. */
	status: string | null,
};

/**  A record a rule rests on, as the library writes one. */
export type RecordRef = {
	/**  The series: `game-change`, `game-behavior`, `mod-artifact`. */
	series: string,
	/**  Its number in the series. */
	number: number,
};

/**  A record opened: its head, its text and the records it names and is named by. */
export type RecordView = {
	/**  The record as the list shows it. */
	head: RecordHead,
	/**  The whole file, as Markdown. */
	markdown: string,
	/**  Every record its text names, each once, sorted, itself left out. */
	cites: string[],
	/**  Every bundled record whose text names it, sorted. */
	cited_by: string[],
};

/**  What a rule does in the structs of its class. */
export type RuleOp = 
/**  Removes fields the target's class does not declare. */
{ op: "remove"; 
/**  The fields. */
fields: string[] } | 
/**  Renames fields, each from a name the target's class does not declare to one it does. */
{ op: "rename"; 
/**  The fields. */
fields: FieldRow[] } | 
/**  Moves fields into a child struct. */
{ op: "move"; 
/**  The child. */
into: ChildSpec; 
/**  The fields. */
fields: FieldRow[] };

/**  A rule: a fixup that is data. */
export type RuleSpec = {
	/**  The name it is turned on and off by. A rule with a built-in fixup's id takes its place. */
	id: string,
	/**  One line for a person. None: the library writes one from the class and the operation. */
	title: string | null,
	/**  The records it rests on. */
	records: RecordRef[],
	/**  Where it runs. */
	phase: FixupPhase,
	/**  Whether a run takes it unless it is turned off. */
	default: boolean,
	/**  The class whose structs it changes. */
	class: string,
	/**  What it does. */
	op: RuleOp,
};

/**  What a kept run was run on and with: what the run page takes to run it again. */
export type RunAgain = {
	/**  A repair or a port. */
	kind: RunKind,
	/**
	 *  The path the archive was last read from, as the person picked it: not cleaned, since
	 *  the run reads the file at it.
	 */
	archive: string,
	/**  The settings the request gave. */
	settings: RunSettings,
	/**  Whether a file is at the path. */
	archive_present: boolean,
};

/**  A finding of the run under way, as it is raised. */
export type RunFinding = {
	/**  The finding, its text as a run without names writes it. */
	finding: Finding,
};

/**  One run of a comparison, as its header shows it. */
export type RunHead = {
	/**  Its number. */
	id: number,
	/**  When the store wrote it, by the store's clock. */
	made_at: string,
	/**  A repair or a port. */
	kind: RunKind,
	/**  The mod's name, as its archive says. */
	name: string | null,
	/**  The mod's version, as its archive says. */
	version: string | null,
	/**  The archive's file name. */
	file_name: string,
	/**  The file name of the `.modpkg` written. */
	package: string | null,
};

/**  What a run makes of a mod. A port unless the request says otherwise (#ADR-0052). */
export type RunKind = 
/**  The mod as it is, at its own slots and paths, its bins fixed (#ADR-0011). */
"repair" | 
/**  The mod over the game's own skin at each unit's target. */
"port";

/**  What a stage of the run under way gave the views, as it ended. */
export type RunPart = {
	/**  The part. */
	part: PartView,
};

/**  What the front end asks a run to do. */
export type RunRequest = {
	/**  A repair or a port. */
	kind?: RunKind,
	/**  The mod archive: a `.fantome`, or a zip of the same layout. */
	archive: string,
	/**  The last stage to run. `write` runs every stage and writes the package. */
	through: StageName,
	/**  The settings. */
	settings: RunSettings,
	/**  The folder the `.modpkg` and its report are written in. Required to write. */
	out: string | null,
};

/**  A run the store keeps, as the Runs page lists it. */
export type RunRow = {
	/**  Its number: the order the runs were written in. */
	id: number,
	/**  Where it came from. */
	origin: Origin,
	/**  The path the project or the package was opened from. None for a run of the app's. */
	opened_from: string | null,
	/**  When the store wrote it, by the store's clock. Shown, never part of a report. */
	made_at: string,
	/**  A repair or a port. */
	kind: RunKind,
	/**  Whether a person marked it kept, so that the bound does not remove it. */
	kept: boolean,
	/**  The archive's SHA-256, as hex. */
	sha256: string,
	/**  The archive's file name. */
	file_name: string,
	/**  The mod's name, as its archive says. */
	name: string | null,
	/**  The mod's author, as its archive says. */
	author: string | null,
	/**  The mod's version, as its archive says. */
	version: string | null,
	/**  The `.modpkg` written. */
	package: string | null,
	/**
	 *  The stages it keeps a snapshot of, in stage order, `load` first. Empty for a run
	 *  opened from a package.
	 */
	reached: StageName[],
	/**
	 *  Whether the ingest tier holds the archive's raw snapshot. A run whose mod was cleared
	 *  from it is read-only until the archive is read again (#ADR-0096). False for a run
	 *  opened from a package, which never had one.
	 */
	archive_ingested: boolean,
};

/**
 *  The settings a run takes, each one the library's (`docs/design/ROADMAP-UX.md`, "Two views
 *  of one run"). The default is the standard set and the default policy.
 */
export type RunSettings = {
	/**  The fixups turned off and on, and the rules added. */
	fixups?: FixupChoice,
	/**  Checks turned off. */
	checks_off?: string[],
	/**  Carry stale copies as the mod's own files. */
	keep_stale?: boolean,
	/**
	 *  Filters of the findings that refuse the write: codes or areas and `key=value` terms.
	 *  None blocks by default (#ADR-0003).
	 */
	block?: string[],
	/**
	 *  How a port chooses each unit's target: `auto`, `base`, `origin`, `slot` or a skin
	 *  number.
	 */
	target?: string,
	/**  The animation reuse a port accepts: `block`, `same-joints`, `own-rig` or `allow`. */
	anim_reuse?: string,
	/**  Cut a port's events from the game's bank only. */
	game_events_only?: boolean,
	/**  Ship each DDS as it is, put in TEX's container nowhere. */
	keep_dds?: boolean,
	/**  Targets given to units alone, each in place of the policy's for that unit (#ADR-0098). */
	unit_targets?: UnitTargetView[],
	/**  Files kept where the run would drop them as stale copies (#ADR-0098, #ADR-0099). */
	kept_files?: KeptFileView[],
	/**  Ship a port's units at slots other than their champion's target too (#ADR-0082). */
	keep_other_slots?: boolean,
};

/**  A stage of the run under way starting or ending. */
export type RunStage = {
	/**  The stage. */
	stage: StageName,
	/**  Whether it started or ended. */
	event: StageEvent,
};

/**  A run as the views show it. The store keeps a saved run's, which reads back. */
export type RunView = {
	/**  Each stage of the run's kind, in order, and how far it got. */
	stages: StageView[],
	/**  The mod, once it was read. */
	meta: ModView | null,
	/**  The fatal finding that ended the run, by its id. */
	halted: number | null,
	/**  Every finding, in the order raised: the inputs' first. */
	findings: Finding[],
	/**  What each fixup did, in the order they ran. */
	changes: FixupChanges[],
	/**  The objects the fixups changed. */
	objects: ObjectView[],
	/**  The decisions, for a port that reached `decide`. */
	targets: TargetsView | null,
	/**  The package, once it was built. */
	package: PackageView | null,
	/**  The `.modpkg` written. */
	written: string | null,
	/**  The run's number in the app's store, once a write kept it there (#ADR-0096). */
	saved: number | null,
	/**  Whether a finding the settings block refused the write. */
	refused: boolean,
	/**  An input that did not answer, which ended the run. */
	fault: string | null,
	/**
	 *  The stage a cancel ended, when one did (#ADR-0097). A kept view without the field
	 *  reads as none.
	 */
	cancelled: StageName | null,
	/**  How long the run took, in milliseconds. Shown, never written to a report. */
	millis: number,
	/**
	 *  A name for each id of the report's tables and of the objects the fixups changed: what
	 *  a finding's fields name by id (`%w0`, `%f12`, `%c0`, `%u0`, `%o14`).
	 */
	names: { [key in string]: string },
};

/**  The schema database in a folder, against the published one. */
export type SchemaCheck = {
	/**  Whether the folder holds a database. */
	held: boolean,
	/**
	 *  Whether an update downloads one: the folder holds none, or another than the one
	 *  published.
	 */
	behind: boolean,
};

/**  The schema database as read. */
export type SchemaView = {
	/**  The file that was read. None when none was found or it did not read. */
	path: string | null,
	/**  The newest build number it describes. */
	latest_build: string | null,
};

/**
 *  A series of numbered records under `docs/`. The library's `Series` names the series code
 *  cites as data; this one holds the decisions too, since the app lists them all.
 */
export type Series = 
/**  A decision. */
"adr" | 
/**  A change Riot made to the game. */
"game-change" | 
/**  How the game client behaves. */
"game-behavior" | 
/**  What tools, mod managers and authors' practices put in mods. */
"mod-artifact";

/**
 *  The app's settings, as `settings.json` holds them.
 * 
 *  A setting the file lacks takes its default, so a file an older app wrote still reads.
 */
export type Settings = {
	/**  The colour scheme. */
	"appearance.theme"?: Theme,
	/**
	 *  The game install a run is judged against, one of the installs listed (#ADR-0101): its
	 *  folder, its `Game` folder or `DATA/FINAL`. None until one is found or added.
	 */
	"inputs.game"?: string | null,
	/**  The game installs added by hand, beside the ones detected (#ADR-0101). */
	"inputs.installs"?: string[],
	/**
	 *  The hash cache's folder. None: the one the League Toolkit programs share on this machine
	 *  (#ADR-0059).
	 */
	"inputs.hashes"?: string | null,
	/**
	 *  The meta schema database. None: the one the League Toolkit programs share on this
	 *  machine (#ADR-0059).
	 */
	"inputs.schema"?: string | null,
	/**
	 *  The history index's folder. None: a run is judged against the install alone
	 *  (#ADR-0047).
	 */
	"inputs.history"?: string | null,
	/**  The folder a package is written in. None: the mod's own folder. */
	"output.folder"?: string | null,
	/**  Run with an input absent, the history index or the hash tables, without asking first. */
	"prompts.runWithLess"?: boolean,
};

/**  How much a finding costs the output, as the report names it. */
export type Severity = 
/**  Nothing is lost. */
"note" | 
/**  The output may differ from what the author saw, or an input limits the run. */
"warning" | 
/**  Something of the mod is not in the output, or is wrong in it. */
"error" | 
/**  There is no output. */
"fatal";

/**  The findings of one run by severity: its own, not the inputs'. */
export type SeverityCounts = {
	/**  Fatal findings. */
	fatal: number,
	/**  Errors. */
	error: number,
	/**  Warnings. */
	warning: number,
	/**  Notes. */
	note: number,
};

/**  The files and bytes of one provenance fact. */
export type SourceCount = {
	/**  The fact, as the load's file provenance names it: `install`, `history` or `own`. */
	fact: string,
	/**  How many files it covers. */
	files: number,
	/**  Their bytes. */
	bytes: number,
};

/**  A stage starting or ending, as a run tells its [`Watch`]. */
export type StageEvent = 
/**  The stage started. */
{ event: "started" } | 
/**  The stage ended, after this many milliseconds. */
{ event: "ended"; millis: number } | 
/**  The run took the stage from a kept run's snapshots, and did not run it. */
{ event: "resumed" };

/**  The files of a kept run at a stage. */
export type StageFiles = {
	/**  The stage. */
	stage: StageName,
	/**  Its WADs, by name. */
	wads: WadFiles[],
};

/**  A stage of a run, in the order they run. */
export type StageName = 
/**  The archive read under its caps. */
"read" | 
/**  The WADs, files, bins and units found. */
"load" | 
/**  The values brought to the target build. */
"fix" | 
/**  What is true of the mod. A port's alone. */
"facts" | 
/**  The target chosen. A port's alone. */
"decide" | 
/**  The units placed. A port's alone. */
"plan" | 
/**  The package built. */
"build" | 
/**  The package checked as the game would apply it. */
"check" | 
/**  The package written. */
"write";

/**  How far a stage got. */
export type StageState = 
/**  It ran to its end. */
"ran" | 
/**  A fatal finding ended the run in it. */
"halted" | 
/**  The run did not reach it. */
"not-run";

/**  A stage of the run and how far it got. */
export type StageView = {
	/**  The stage. */
	stage: StageName,
	/**  How far it got. */
	state: StageState,
	/**  How long it took, in milliseconds, when it ran. */
	millis: number | null,
	/**
	 *  Whether the run took it from a kept run's snapshots in place of running it. A kept
	 *  view without the field reads as false.
	 */
	resumed?: boolean,
};

/**  What the app keeps on disk for the history, as the inputs page shows it. */
export type StorageView = {
	/**  The bytes of the index the settings choose. Zero when they choose none. */
	index_bytes: number,
	/**  Whether the index the settings choose is one the app installed. */
	index_owned: boolean,
	/**
	 *  The index with the most builds among those the app installed and the settings do not
	 *  choose.
	 */
	kept: KeptIndex | null,
	/**
	 *  The bytes of every index the app installed, the one the settings choose among them: what
	 *  their removal frees.
	 */
	indexes_bytes: number,
	/**  The bytes of the app's clones of the census history. */
	census_bytes: number,
	/**  The bytes of the downloads kept to resume. */
	downloads_bytes: number,
};

/**  The store's state, as the pages show it. */
export type StoreState = 
/**  It is open: runs are kept. */
({ state: "open" }) & { detail?: never } | 
/**  Its rows' file is another build's: runs are not kept until a reset. */
{
	state: "outdated",
} & Outdated | 
/**  It did not open: runs are not kept. */
{ state: "failed"; 
/**  Why, as the OS or SQLite says it. */
detail: string };

/**  What the store holds, as the settings page's storage group shows it. */
export type StoreView = {
	/**  The runs kept. */
	runs: number,
	/**  The runs marked kept. */
	kept: number,
	/**  The mods the runs are of. */
	mods: number,
	/**  The bytes of the rows' file. */
	rows_bytes: number,
	/**  The bytes of the run tier. */
	tier_bytes: number,
	/**  The bytes of the ingest tier. */
	ingest_bytes: number,
	/**
	 *  The bytes of the blobs the ingest tier's entries name whose archive no run is of: what
	 *  clearing the unused archive data frees at most, since a blob two entries share is
	 *  counted in each.
	 */
	ingest_unused_bytes: number,
};

/**  What a finding is about. */
export type Subject = {
	/**  The kind of thing: `wad`, `file`, `object`, `input`. */
	kind: string,
	/**  The id the report's tables join on. */
	id: string,
	/**  The name for a person. */
	name: string,
};

/**  One unit's target in either run of a port. */
export type TargetDiff = {
	/**  The unit, as its character and slot name it: `Ahri skin3`. */
	unit: string,
	/**  The character's name. */
	character_name: string,
	/**  The first run's target. None: the unit left to the game, or absent from the run. */
	a: number | null,
	/**  The second run's target. */
	b: number | null,
	/**  Why the first run chose it, as the library names it. Empty for a unit it lacks. */
	a_reason: string,
	/**  Why the second run chose it. */
	b_reason: string,
	/**  Whether the target or the reason differs. */
	differs: boolean,
};

/**  The decisions of a port. */
export type TargetsView = {
	/**  The policy the run decided under. */
	policy: PolicyView,
	/**  One decision per unit. */
	decisions: DecisionView[],
};

/**  A colour scheme. */
export type Theme = 
/**  The system's. */
"system" | 
/**  Dark. */
"dark" | 
/**  Light. */
"light";

/**
 *  A target given to one unit (#ADR-0098): the unit by its character and the slot the mod
 *  ships it at, and the slot it ships to.
 */
export type UnitTargetView = {
	/**  The character's name, as the mod's directory spells it. */
	character: string,
	/**  The slot the mod ships the unit at. */
	slot: number,
	/**  The slot it ships to. None: it is left to the game. */
	target: number | null,
};

/**  A skin unit of the mod. */
export type UnitView = {
	/**  Its id in the report: `%u0`. */
	id: string,
	/**  Its character's name. */
	character_name: string,
	/**  The slot its bin sits in. */
	slot: number,
	/**  Its skin bin's path, else its hash. */
	file: string,
	/**  The slot its skin entry's name spells. */
	entry_name_slot: number | null,
	/**  How many bins the client loads for it, the skin bin among them. */
	loads: number,
};

/**  How far an update of the index has got, for the window to show. */
export type UpdateStep = 
/**  The census history is fetching. */
{ kind: "fetch"; 
/**  The objects asked for. */
objects: number; 
/**  The bytes read. */
bytes: number } | 
/**  The builds are appending. */
{ kind: "append"; 
/**  The builds the index holds so far. */
done: number; 
/**  The builds it holds once the append ends. */
of: number; 
/**  The build appended last. */
build: string };

/**  A value on one line, with its kind. */
export type ValueView = {
	/**  The value's kind, as the meta schema names kinds. */
	kind: string,
	/**  The value on one line. */
	text: string,
};

/**  The files of one WAD at a stage. */
export type WadFiles = {
	/**
	 *  The WAD's name. A layer other than the base one names its WADs under it:
	 *  `hud/Ahri.wad.client`.
	 */
	name: string,
	/**  Its files in path order, the ones named by their hash alone last. */
	files: FileRow[],
};

/**  A WAD of the mod. */
export type WadView = {
	/**  Its id in the report: `%w0`. */
	id: string,
	/**  Its name as the archive spells it. */
	name: string,
	/**  Whose it is: `champion`, `locale` or `other`. */
	role: string,
	/**  How the archive holds it: `loose` or `packed`. */
	layout: string,
	/**  How many files it holds. */
	files: number,
	/**  How many of them have a path the archive or the names spell. */
	named: number,
	/**  The locale of a locale WAD taken as its champion's. */
	packed_locale: string | null,
	/**  Whether it restores a champion's model from before its rework. */
	restoration: boolean,
};

/* Tauri Specta runtime */
type EventEmit<T> = [T] extends [null] ? () => Promise<void> : (payload: T) => Promise<void>;

function makeEvent<T>(name: string, serialize?: (payload: T) => unknown, deserialize?: (payload: any) => T) {
    const mapEvent = (cb: __TAURI_EVENT.EventCallback<T>) => (event: __TAURI_EVENT.Event<any>) => cb({ ...event, payload: deserialize ? deserialize(event.payload) : event.payload });
    const mapPayload = (payload: T) => serialize ? serialize(payload) : payload;

    const base = {
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => __TAURI_EVENT.once(name, mapEvent(cb)),
        emit: ((payload: T) => __TAURI_EVENT.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    };

    const fn = (target: import("@tauri-apps/api/webview").Webview | import("@tauri-apps/api/window").Window) => ({
        listen: (cb: __TAURI_EVENT.EventCallback<T>) => target.listen(name, mapEvent(cb)),
        once: (cb: __TAURI_EVENT.EventCallback<T>) => target.once(name, mapEvent(cb)),
        emit: ((payload: T) => target.emit(name, mapPayload(payload)) as unknown) as EventEmit<T>
    });

    return Object.assign(fn, base);
}

